export const MAP = { width: 1000, height: 389, latMax: 83, latMin: -57 } as const

/** Converte [latitude, longitude] em porcentagem (0-100) sobre o mapa. */
export function project(lat: number, lon: number) {
  return { x: ((lon + 180) / 360) * 100, y: ((MAP.latMax - lat) / (MAP.latMax - MAP.latMin)) * 100 }
}

